const input = $input.first().json || {};
const headers = input.headers || {};
const expected = String( $env.LMT_MEDIA_MASTER_TOKEN || '' );
const received = String( headers.authorization || headers.Authorization || '' );
const wanted = `Bearer ${ expected }`;

function safeEqual( left, right ) {
  let mismatch = left.length ^ right.length;
  const length = Math.max( left.length, right.length );
  for ( let index = 0; index < length; index++ ) {
    mismatch |= ( left.charCodeAt( index ) || 0 ) ^ ( right.charCodeAt( index ) || 0 );
  }
  return mismatch === 0;
}

const authorised = expected.length >= 32 && safeEqual( received, wanted );
return [ { json: { ...input, authorised } } ];

// Plugin posts: { image: "data:<mime>;base64,....", mime, prompt, site:{url,name} }
const body = ($input.first().json.body) || {};

const dataUri = body.image || '';
const prompt  = body.prompt || 'Write a concise, descriptive alt text for this image. Return only the alt text.';

// Strip the data URI prefix -> raw base64. Bedrock Converse wants base64 bytes WITHOUT the "data:...;base64," prefix.
let base64 = dataUri;
const comma = dataUri.indexOf(',');
if (dataUri.startsWith('data:') && comma !== -1) {
  base64 = dataUri.slice(comma + 1);
}

// Map mime -> Bedrock image format token
const mime = (body.mime || 'image/jpeg').toLowerCase();
const map = {
  'image/jpeg': 'jpeg',
  'image/jpg':  'jpeg',
  'image/png':  'png',
  'image/gif':  'gif',
  'image/webp': 'webp'
};
const format = map[mime] || 'jpeg';

// Bedrock Converse request body (Nova Lite supports image input)
const requestBody = {
  messages: [
    {
      role: 'user',
      content: [
        { image: { format, source: { bytes: base64 } } },
        { text: prompt }
      ]
    }
  ],
  inferenceConfig: { maxTokens: 600, temperature: 0.2 }
};

return [{ json: { requestBody } }];

const body = $input.first().json || {};
const content = body.output && body.output.message && Array.isArray( body.output.message.content )
  ? body.output.message.content
  : [];
const part = content.find( item => item && typeof item.text === 'string' );
const text = part ? part.text.trim() : '';
return [ { json: { text } } ];
